@Component("dataSet-subscriber")
public class DataSetSubscriber extends BaseSubscriber {

	public DataSetSubscriber() {
	}
	
    public SubscriptionQueryResult<List<DataSet>, DataSet> dataSetSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllDataSetQuery(), 
                		ResponseTypes.multipleInstancesOf(DataSet.class),
                		ResponseTypes.instanceOf(DataSet.class));
    }

    public SubscriptionQueryResult<DataSet, DataSet> dataSetSubscribe(@DestinationVariable UUID dataSetId) {
        return queryGateway
                .subscriptionQuery(new FindDataSetQuery(new LoadDataSetFilter(dataSetId)), 
                		ResponseTypes.instanceOf(DataSet.class),
                		ResponseTypes.instanceOf(DataSet.class));
    }





}

